afterExample:
import org.eclipse.jface.dialogs.MessageDialog;
import org.eclipse.swt.widgets.Shell;

public class Example {
    public void handleError(Shell shell, String title, Exception e) {
        MessageDialog.openError(shell, title, e.getMessage() == null ? e.toString() : e.getMessage());
    }
}

