import org.eclipse.jface.dialogs.MessageDialog;
import org.eclipse.swt.widgets.Shell;

public class Example {
    public void handleOtherError(Shell shell, String title, Exception e) {
        // This should not be changed as it provides a custom message
        MessageDialog.openError(shell, title, "An error occurred: " + e.getLocalizedMessage());

        // This should not be changed as it uses a different method
        MessageDialog.openError(shell, title, e.getLocalizedMessage());

        // This should not be changed if the third argument is not e.getMessage()
        String customMsg = "Some info";
        MessageDialog.openError(shell, title, customMsg);
    }
}
